const sampleManifest = (prefix, size, cargo, count, status = '已完成') => Array.from({ length: 5 }, (_, index) => ({
  key: `${prefix}-${index + 1}`,
  containerNo: `${prefix}${String(index + 1).padStart(4, '0')}`,
  size,
  cargo,
  sealNo: `SL${String(83010 + index)}`,
  weight: size === '40GP' ? '30.80' : '18.60',
  status,
  totalCount: count,
}))

